static bool multiple_pipes_ok ( struct intel_crtc * crtc , struct intel_plane_state * plane_state ) { struct drm_i915_private * dev_priv = to_i915 ( crtc -> base . dev ) ; struct intel_fbc * fbc = & dev_priv -> fbc ; enum pipe pipe = crtc -> pipe ; if ( plane_state -> base . visible ) { fbc -> visible_pipes_mask |= ( 1 << pipe ) ; } else { fbc -> visible_pipes_mask &= ~ ( 1 << pipe ) ; } return ( fbc -> visible_pipes_mask & ~ ( 1 << pipe ) ) != 0 ; } 